import{_ as t,o as r,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月29日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-29.md","filePath":"science-log/src/reconstructed/2026-07-29.md"}'),a={name:"science-log/src/reconstructed/2026-07-29.md"};function s(g,o,i,u,l,h){return r(),n("div",null,[...o[0]||(o[0]=[e('<h1 id="🔬-科学快报-2026年7月29日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月29日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月29日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月29日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 命中 20 条 / Science 10.1126 命中 19 条 / PNAS 0027-8424 命中 17 条）+ arXiv 日期区间 <code>[202607290000 TO 202607292359]</code>（cs.AI，命中 30 篇）｜ 摘要经 EuropePMC <code>resultType=core</code> 回填 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🦠-痘病毒-门户复合体-原位结构-一座贯穿核心壁的六聚体闸门" tabindex="-1">🦠 痘病毒&quot;门户复合体&quot;原位结构：一座贯穿核心壁的六聚体闸门 <a class="header-anchor" href="#🦠-痘病毒-门户复合体-原位结构-一座贯穿核心壁的六聚体闸门" aria-label="Permalink to &quot;🦠 痘病毒&quot;门户复合体&quot;原位结构：一座贯穿核心壁的六聚体闸门&quot;">​</a></h3><p><strong>In situ structure of the poxvirus portal complex</strong><em>Nature（2026-07-29）</em></p><p>痘病毒（天花、猴痘的病原家族）成熟时要在膜内筑出一个<strong>双凹核心</strong>，而核心壁上那个让 mRNA 得以释放的&quot;孔&quot;，其分子构造长期不清楚。Thomas Calcraft、Miguel Hernandez-Gonzalez、Michael Way 与 Peter B. Rosenthal 用<strong>冷冻电镜断层扫描（cryo-ET）+ 亚断层平均 + 结构预测</strong>，在疫苗病毒（vaccinia）上解出了这个门户复合体：它由 <strong>E8、E6、L3</strong> 三种在痘病毒中高度保守的蛋白组成，<strong>E6 六聚体</strong>构成中央腔室并咬住核心壁，<strong>E8 六聚体</strong>贴在 E6 外侧，**L3 以&quot;二聚体的六聚体&quot;**形式结合在内侧；释放基因组所需的解旋酶 <strong>D5</strong> 在感染时停靠到外侧 E8 环上。三种组分的空间分工，等于把&quot;装配&quot;与&quot;出关&quot;两个过程画进了同一张结构图。作者据此提出，门户复合体是抗痘病毒药物一个相当有吸引力的靶点。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10856-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10856-2</a></p><h3 id="♻️-co2-与双环烷烃交替共聚-把-惰性气体-做成可闭环回炉的高性能聚酯" tabindex="-1">♻️ CO₂ 与双环烷烃交替共聚：把&quot;惰性气体&quot;做成可闭环回炉的高性能聚酯 <a class="header-anchor" href="#♻️-co2-与双环烷烃交替共聚-把-惰性气体-做成可闭环回炉的高性能聚酯" aria-label="Permalink to &quot;♻️ CO₂ 与双环烷烃交替共聚：把&quot;惰性气体&quot;做成可闭环回炉的高性能聚酯&quot;">​</a></h3><p><strong>Alternating CO2 and bicycloalkane copolymerization to circular polyesters</strong><em>Nature（2026-07-29）</em></p><p>CO₂ 与烯烃的交替共聚在热力学上是走不通的，所以六十年来把 CO₂ 变聚酯只能绕道高活性共聚单体。Min Zhu、Xavier Westworth、Yingluo Zhao、Gaurav S. Deshmukh、Deepak K. Barange、Tao Zhang、Ravikumar R. Gowda、Linda J. Broadbelt 等 9 位作者换了个搭档：让 CO₂ 直接与<strong>双环丁烷（BCB）、双环戊烷（BCP）<strong>在</strong>简单有机催化剂</strong>引发下<strong>完美交替</strong>共聚，得到 <strong>CO₂ 摩尔分数上限 50%、高分子量</strong>的聚酯，主链上保留的环结构还能调节热学与力学性能。性能与&quot;终局&quot;被刻意做成了正交的两件事：BCB-CO₂ 聚酯在<strong>全 pH 范围</strong>内耐热耐水解，却能在本体或碱催化条件下<strong>选择性解聚，回收到纯度合格的 BCB 单体，分离收率 &gt;90%</strong>；BCP-CO₂ 则解聚为双环内酯。多轮&quot;解聚—再聚合&quot;循环，把这类材料变成了真正闭环的生命周期，而不是&quot;可回收&quot;口号。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10848-2" target="_blank" rel="noreferrer">10.1038/s41586-026-10848-2</a></p><h3 id="⚡-只剩八面体的-co3o4-酸性电解水把铱拉下马的一步" tabindex="-1">⚡ 只剩八面体的 Co₃O₄：酸性电解水把铱拉下马的一步 <a class="header-anchor" href="#⚡-只剩八面体的-co3o4-酸性电解水把铱拉下马的一步" aria-label="Permalink to &quot;⚡ 只剩八面体的 Co₃O₄：酸性电解水把铱拉下马的一步&quot;">​</a></h3><p><strong>Octahedral-coordinated Co3O4 for water electrolysis in acid</strong><em>Nature（2026-07-29）</em></p><p>酸性析氧（OER）几乎被铱基材料垄断，因为非贵金属氧化物在这个环境里既不够活也不够稳。传统尖晶石 Co₃O₄ 的病灶很明确：惰性的<strong>四面体（T_d）<strong>位点与高活性的</strong>八面体（O_h）<strong>位点共存。Yue Wang、Yujin Ji、Jing Zhou 等 17 位作者用</strong>真空介导的熔碱机械化学法</strong>做出了新的<strong>三方相 Co₃O₄（Tri-Co₃O₄）</strong>：空间群 <em>P-3m1</em>（164），只有<strong>共边 [CoO₆] 八面体</strong>，三层密堆结构里 Co²⁺ 与 Co³⁺ 以 <strong>1:2</strong> 全部落在八面体位。结果落在两个硬指标上——酸性 OER 在 10 mA cm⁻² 下过电位仅 <strong>269 mV，比尖晶石低 181 mV</strong>；装进质子交换膜电解槽（PEMWE），<strong>1.80 V 下电流密度超过 1800 mA cm⁻²</strong>。机理上，二维共边八面体层同时优化了中间体吸附并抑制 Co 溶出，活性与稳定性这次没有互相拆台。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10851-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10851-7</a></p><h3 id="🌊-海洋铁施肥的账本-效率高的地方-生态代价也高" tabindex="-1">🌊 海洋铁施肥的账本：效率高的地方，生态代价也高 <a class="header-anchor" href="#🌊-海洋铁施肥的账本-效率高的地方-生态代价也高" aria-label="Permalink to &quot;🌊 海洋铁施肥的账本：效率高的地方，生态代价也高&quot;">​</a></h3><p><strong>Climate benefit and ecological cost trade-offs for ocean iron fertilization</strong><em>Nature（2026-07-29）</em></p><p>海洋铁施肥（OIF）一直被当作潜在 CDR 手段讨论，但&quot;能固多少碳&quot;与&quot;会毁多少生态&quot;的权衡缺乏定量账本。Jun Yu、J. Keith Moore、Francois W. Primeau、Anthony F. Michaels 等 11 位作者用一套<strong>过程完整、含海洋生物多样性与生物地球化学验证表征</strong>的模式，在<strong>十大洋区、60 年</strong>尺度上逐区结算。结论是区域分化极大：南大洋与赤道太平洋效率最高，但路径不同——<strong>前者靠向下的&quot;非局地&quot;碳输出</strong>，<strong>后者靠局地输出加下游损失</strong>（施肥水华把源区宏量营养盐耗尽，反而压制了别处的生产力）。代价也随之落在赤道：能量向高营养级的输送被削弱，<strong>氧最小带（OMZ）扩张</strong>，大型浮游动物生物量下降；把部署北移可规避大部分影响。恢复实验显示南大洋有韧性、赤道太平洋则因区域铁滞留而扰动持续。60 年净 CDR 仅 <strong>1.1–5.3 ppm</strong>，且<strong>过半在施肥结束后的几十年内被重新释放</strong>——局地干预与全球结果之间的这道断层，让碳信用与治理都难以落地。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10795-y" target="_blank" rel="noreferrer">10.1038/s41586-026-10795-y</a></p><h3 id="🧬-线粒体核糖体-掉了组织度-人类-t-细胞衰老的一个纳米级解释" tabindex="-1">🧬 线粒体核糖体&quot;掉了组织度&quot;：人类 T 细胞衰老的一个纳米级解释 <a class="header-anchor" href="#🧬-线粒体核糖体-掉了组织度-人类-t-细胞衰老的一个纳米级解释" aria-label="Permalink to &quot;🧬 线粒体核糖体&quot;掉了组织度&quot;：人类 T 细胞衰老的一个纳米级解释&quot;">​</a></h3><p><strong>Cryoelectron tomography reveals an age-related decline in mitoribosomes that contributes to T cell dysfunction in older individuals</strong><em>PNAS（2026-07-29）</em></p><p>小鼠证据早就把 T 细胞衰老指向线粒体功能障碍，但人类 T 细胞是否同构一直争议不断——原因之一是缺&quot;原位&quot;观测。Jingwen Chen、Lili Su、Bangze Pan、Junhao Sang、Linlin Li、Junsong Huang、Zhao-Lan Hu、Lixin Wang 等 10 位作者用<strong>冷冻电镜断层扫描</strong>，在生理状态下直接解析原代人 <strong>CD8⁺ T 细胞</strong>内线粒体核糖体的结构与空间排布，发现衰老伴随<strong>线粒体核糖体丰度下降</strong>，更关键的是<strong>支持&quot;协同翻译&quot;的高级有序排布解体</strong>。因果链由此被接上：线粒体翻译受损 → 胞质核糖体蛋白表达受抑 → 线粒体生物合成受限 → 线粒体质量下降 → 记忆表型与增殖能力双降。可逆性也做了验证：过表达线粒体核糖体组分 <strong>Mrps5</strong>，能在病毒感染或肿瘤小鼠模型中<strong>逆转衰老 T 细胞表型</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2608102123" target="_blank" rel="noreferrer">10.1073/pnas.2608102123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🫁-orca-不给-3d-ct-做-网格平均-按器官质心压-token" tabindex="-1">🫁 ORCA：不给 3D CT 做&quot;网格平均&quot;，按器官质心压 token <a class="header-anchor" href="#🫁-orca-不给-3d-ct-做-网格平均-按器官质心压-token" aria-label="Permalink to &quot;🫁 ORCA：不给 3D CT 做&quot;网格平均&quot;，按器官质心压 token&quot;">​</a></h3><p><strong>ORCA: ORgan-Centroid Aggregation for Training-Free 3D CT Visual Token Compression</strong><em>arXiv（2026-07-29）</em></p><p>一个 3D CT 体积送进视觉语言模型，动辄产生数千到数万个视觉 token，必须在进语言模型前压缩。Renjie Liang、Zijian Xu、Jinqian Pan、Chengkun Sun、Zhengkang Fan、Shawn Li、You Qin、Mei Liu、Jie Xu 指出常见基线&quot;网格平均&quot;的根本毛病：规则网格池化会把<strong>不同解剖结构、病灶与空气混进同一个 token</strong>。<strong>ORCA</strong> 改为<strong>按器官引导合并相邻 token</strong>，并给每个区域叠加<strong>质心的正弦编码</strong>以保住空间布局；它<strong>免训练、即插即用</strong>，不需要改模型、也不需要文本查询就能给出可调 token 集。在 CT-RATE 与 Merlin 两个数据集、五种编码器、属性预测（大小/密度/位置/纹理/疾病五族）与文本生成（VQA、报告生成）两类任务上，同 token 预算下全面优于既有压缩法：视觉上下文缩 <strong>64×</strong>、KV-cache 缩 <strong>50×</strong>、单体积处理快 <strong>31×</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00345" target="_blank" rel="noreferrer">2608.00345</a></p><h3 id="⚖️-同一组数字-换个说法就换个结论-ai-智能体的-动机性推理" tabindex="-1">⚖️ 同一组数字，换个说法就换个结论：AI 智能体的&quot;动机性推理&quot; <a class="header-anchor" href="#⚖️-同一组数字-换个说法就换个结论-ai-智能体的-动机性推理" aria-label="Permalink to &quot;⚖️ 同一组数字，换个说法就换个结论：AI 智能体的&quot;动机性推理&quot;&quot;">​</a></h3><p><strong>Bayesian and Motivated Reasoning in AI Agents</strong><em>arXiv（2026-07-29）</em></p><p>Eddie Yang 做了一个近乎心理学实验的设计：<strong>把证据完全固定</strong>，只改换证据出现的场景框架，看智能体的结论是否漂移。场景选在三个高风险领域——<strong>医学、选举取证、地缘政治预测</strong>，共 <strong>12 组智能体×领域对照</strong>。结果是系统性的：智能体的结论强烈受<strong>先验信念</strong>牵引，当结论被包装成它本就认为&quot;很可能&quot;的命题时，给出肯定判断的概率显著上升，框架与先验冲突时则相反；框架甚至改变了<strong>工作方式</strong>——有的智能体检索更广、选择不同的分析设定、对同一份证据给出不同评价。作者点出的风险很具体：把决策委托给智能体时，最终结论可能依赖于<strong>既未写在任务里、也不在决策记录中</strong>的先验。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00339" target="_blank" rel="noreferrer">2608.00339</a></p><h3 id="💠-crystalmem-内存被-挤压-之后-能力不会自己长回来" tabindex="-1">💠 CrystalMem：内存被&quot;挤压&quot;之后，能力不会自己长回来 <a class="header-anchor" href="#💠-crystalmem-内存被-挤压-之后-能力不会自己长回来" aria-label="Permalink to &quot;💠 CrystalMem：内存被&quot;挤压&quot;之后，能力不会自己长回来&quot;">​</a></h3><p><strong>CrystalMem: Elastic Memory for Self-Evolving LLM Agents via Knowledge Crystallization</strong><em>arXiv（2026-07-29）</em></p><p>云平台的配额会随负载与成本上下调整，但 Beining Wu 与 Jun Huang 发现能力<strong>并不跟着预算对称回升</strong>：经历一轮&quot;挤压—恢复&quot;后智能体稳定停在低于挤压前的水平，他们称之为<strong>记忆滞后（memory hysteresis）</strong>。原因是结构性的——删除与单向压缩丢掉了日后重建所需的材料，作者进而<strong>证明</strong>：任何&quot;只保留或丢弃条目&quot;的策略都存在一个<strong>残余亏空下界</strong>。<strong>CrystalMem</strong> 因此把记忆做成弹性边车：条目在<strong>四种保真度状态</strong>间按&quot;结晶能量&quot;调度降级，降级顺序由<strong>优势加权影响度 + 依赖耦合</strong>决定，能力恢复则靠<strong>有验证的重结晶</strong>，且受显式算力与字节上限约束。在 <strong>7 个环境、17 种方法、6 个骨干</strong>，含多租户服务与真实边云部署的评测中，它的恢复能力在每一设置下都最高；<strong>只用 50% 字节预算</strong>即追平最强预算内基线在全额供给下的表现，等预算下平均领先 <strong>+4.6 pp</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00303" target="_blank" rel="noreferrer">2608.00303</a></p><h3 id="🕸-hyperagent-按-输入-schema-→-输出-schema-把工具连成超图再规划" tabindex="-1">🕸 HyperAgent：按&quot;输入 schema → 输出 schema&quot;把工具连成超图再规划 <a class="header-anchor" href="#🕸-hyperagent-按-输入-schema-→-输出-schema-把工具连成超图再规划" aria-label="Permalink to &quot;🕸 HyperAgent：按&quot;输入 schema → 输出 schema&quot;把工具连成超图再规划&quot;">​</a></h3><p><strong>HyperAgent: Planning and Acting over Tool-Schema Hypergraphs for Tool-Use LLM Agents</strong><em>arXiv（2026-07-29）</em></p><p>让 LLM 从工具的文字描述里&quot;猜&quot;工具怎么串，是当前工具型智能体不可靠的根源：探索低效、执行易断。Zian Zhai、Xingyu Tan、Gaowang Zou、Xiaoyang Wang、Wenjie Zhang 把工具关系<strong>提到 schema 层</strong>建模，构造<strong>有向&quot;工具—schema&quot;超图</strong>——每个工具是一条从&quot;所需输入 schema 节点&quot;指向&quot;输出 schema 节点&quot;的超边。<strong>HyperAgent</strong> 先把任务相关的工具上下文图抽出来，据此构建<strong>schema 感知的任务 DAG</strong>；执行时再按当前状态做<strong>亏空导向扩张</strong>，识别未满足的需求并检索能&quot;生产&quot;它的工具，形成状态条件下的工具支撑图。在 <strong>AppWorld</strong> 上，它提升了任务完成率，同时减少<strong>冗余 API 调用、LLM 交互次数与 token 消耗</strong>——规划的结构化省下了试错的成本。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.02650" target="_blank" rel="noreferrer">2608.02650</a></p><h3 id="🎭-心智理论不是一种能力-前沿视觉语言模型在两个任务上-人格分裂" tabindex="-1">🎭 心智理论不是一种能力：前沿视觉语言模型在两个任务上&quot;人格分裂&quot; <a class="header-anchor" href="#🎭-心智理论不是一种能力-前沿视觉语言模型在两个任务上-人格分裂" aria-label="Permalink to &quot;🎭 心智理论不是一种能力：前沿视觉语言模型在两个任务上&quot;人格分裂&quot;&quot;">​</a></h3><p><strong>Cross-Task Dissociation in Frontier Vision-Language Model Theory of Mind</strong><em>arXiv（2026-07-29）</em></p><p>前沿视觉语言模型的心智理论（ToM）到底是一个连贯的画像，还是随范式碎裂？Kejia Zhang、Youran Sun、Chugang Yi、Haizhao Yang 用同一批 <strong>9 个前沿 VLM</strong> 跑两个源自心理学的基准：<strong>Keysar 指令任务</strong>（自我中心干扰下的视觉视角采择）与<strong>Frith-Happé 动画三角</strong>（用 Castelli 评分表从纯运动判读意图）。结果分裂得很彻底：Director 任务上，不启用思维链时模型在 <strong>78% 试次</strong>犯下与<strong>儿童</strong>相同的自我中心错误（推理能救回若干模型）；三角任务上则系统性<strong>低判意图</strong>，其 ToM 画像距<strong>高功能自闭症成人（HF-ASD）均值</strong>比距<strong>典型发展成人（TD）均值</strong>近三倍以上，而&quot;目标导向&quot;&quot;随机&quot;两项仍贴近 TD。<strong>没有任何模型在两个任务上都最接近 TD</strong>：Director 上像成人的，三角上落在 HF-ASD 一侧；三角上最像 TD 的，Director 上又像儿童。作者明确只报群体层面描述，不给模型贴诊断标签。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.00261" target="_blank" rel="noreferrer">2608.00261</a></p><blockquote><p>📅 日期：2026-07-29 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const q=t(a,[["render",s]]);export{p as __pageData,q as default};
